def solve():
    try:
        input_data = sys.stdin.read().split()
        if not input_data:
            return
        n = int(input_data[0])
        t = input_data[1]
    except Exception:
        return

    s = []
    idx = 0
    for length in range(1, len(t) + 1):
        if idx >= n:
            break
        # Take the next 'length' characters as a block
        if idx + length <= n:
            block = t[idx:idx + length]
            if all(c == block[0] for c in block):
                s.append(block[0])
                idx += length
            else:
                # This should not happen based on problem guarantee
                break
        else:
            break

    print("".join(s))

if __name__ == "__main__":
    solve()

