import sys

def solve():
    try:
        input_data = sys.stdin.read().split()
        if not input_data:
            return
        n = int(input_data[0])
        t = input_data[1]

        s = []
        length = 0
        for i in range(1, n + 1):
            start = length
            end = length + i
            if end <= n:
                s.append(t[start])
                length = end
            else:
                break

        print("".join(s))
    except Exception:
        pass

if __name__ == "__main__":
    solve()
